ACC = ['key:Escape', 'user:accountant', 'click:menutop:Accounts & Reports', 'click:menuleaf:Accounting']
chapter(21, 'Accounting', 'Read the vouchers HCC posts by itself, enter a contra and an owner drawing, get them approved, and read the trial balance, statements, profit and loss, balance sheet, ageing, GST, TDS, assets, Tally export, bank reconciliation and year end.',
        'Farhan (Accountant)', 'accountant', menu='Accounts & Reports > Accounting')
step('Farhan, the Accountant, is on Modules Home. Accounting is the last stop of the money that the other chapters moved.', 'Every receipt, bill and payout of the hotel already has a voucher; the accountant checks and completes them.', target='sel:.fit-home-grid', auto=['key:Escape', 'user:accountant'], action='read', expect='Modules Home for Farhan.', check="ctx.uid==='accountant'")
tile('Accounts & Reports', 'Click the Accounts & Reports tile.', 'Accounting sits with day closing and the reports.', expect='The Accounts & Reports page opens.')
leaf('Accounts & Reports', 'Accounting', 'Click the Accounting tile.', 'The page has one tab for every accounting job.', expect='The Accounting page opens on Vouchers.', check="ctx.page==='accounting'")
read('The Vouchers tab lists the vouchers of the chosen business date: sales vouchers SAL, receipts RCT and payments PMT, each numbered with the date. HCC creates them from the folios, the cashier and the expenses; nobody types them.', 'The accounts follow the hotel\'s work, so the books are never behind.', target='sel:main h1', expect='The vouchers of 26 Oct.')
click('tab:Manual vouchers', 'Open the Manual vouchers tab.', 'Entries that no screen of the hotel creates are made here by hand.', expect='The manual voucher types are offered.')
click('btn:Contra', 'Click Contra (cash and bank). The reception cash is taken to the bank.', 'A contra moves money between the cash drawer and the bank without any income or expense.', expect='The Contra dialog opens.', check="has('Send for approval')")
step('Choose From the front-desk cash, To the hotel current account, the amount 20000 and the narration: Cash taken to the bank.', 'The narration says in words what the entry is, for the auditor.', target='field:Amount', auto=['select:field:From|TILL', 'select:field:To|Hotel current', 'type:field:Amount|20000', 'type:field:Narration|Cash taken to the bank'], action='type', expect='The contra is filled.')
click('modalbtn:Send for approval', 'Click Send for approval.', 'A manual voucher is posted only after another user approves it.', expect='The voucher waits for approval.')
click('btn:Owner drawing', 'Click Owner drawing from the bank.', 'When the owner takes money out of the business, it is a drawing and not an expense.', expect='The Owner drawing dialog opens.', check="has('Send for approval')")
step('Choose the hotel current account, the amount 10000 and the narration: Owner drawing for personal use.', 'A drawing reduces the owner\'s capital, not the profit.', target='field:Amount', auto=['select:field:Taken from bank account|Hotel current', 'type:field:Amount|10000', 'type:field:Narration|Owner drawing for personal use'], action='type', expect='The drawing is filled.')
click('modalbtn:Send for approval', 'Click Send for approval.', 'The owner approves his own drawing through the approval list, so that the record is complete.', expect='The drawing waits for approval.')
step('Sagar, the Owner, opens Accounting, Manual vouchers and the Pending approval list.', 'The owner sees every manual entry before it is posted.', target='btn:Pending approval', auto=['key:Escape', 'user:owner', 'click:menutop:Accounts & Reports', 'click:menuleaf:Accounting', 'click:tab:Manual vouchers'], action='click', expect='The manual vouchers with the pending ones.', check="has('Pending approval')")
click('btn:Pending approval', 'Click Pending approval.', 'The list shows the contra and the drawing sent by Farhan.', expect='The two vouchers are listed.')
click('btn:Approve', 'Click Approve on the first voucher, the contra.', 'The approver reads the narration and the amount first; the voucher is then posted to the ledgers with its own number.', expect='The contra is approved and posted.')
click('btn:Approve', 'Click Approve on the second voucher, the owner drawing.', 'Nobody approves their own entry, which is why the Owner approves what the Accountant prepared.', expect='The drawing is approved and posted.')
step('Back as Farhan, open the GST month tab.', 'The GST of the month is set off here: output tax on sales against input credit on purchases and expenses.', target='tab:GST month', auto=ACC + ['click:tab:GST month'], action='click', expect='The GST month page opens.')
click('tab:TDS', 'Open the TDS tab.', 'Tax deducted at source from contractors is recorded with the payee type and the rate, to be paid to the government by the due date.', expect='The TDS page opens.')
click('tab:Assets', 'Open the Assets tab.', 'The asset register lists furniture, machines and vehicles with their cost, date and depreciation.', expect='The asset register opens.')
click('tab:Trial balance', 'Open the Trial balance tab.', 'The trial balance lists every ledger with opening, debit, credit and closing; the debits must equal the credits.', expect='The trial balance opens.')
click('tab:Statements', 'Open the Statements tab.', 'A ledger or party statement shows every entry of one account; for a company it is the statement sent for payment.', expect='The statements page opens.')
click('tab:P&L', 'Open the P&L tab.', 'The profit and loss statement shows income, expenses and the profit of a period.', expect='The profit and loss statement opens.')
click('tab:Balance sheet', 'Open the Balance sheet tab.', 'The balance sheet shows what the hotel owns and owes on a date.', expect='The balance sheet opens.')
click('tab:Outstanding', 'Open the Outstanding tab.', 'Ageing lists the money owed by companies and by guests in groups of days; the company credit of Shree Agro Industries is here.', expect='The outstanding amounts by age are listed.')
click('tab:GST summary', 'Open the GST summary tab.', 'The summary shows taxable value, CGST and SGST for each rate, ready for the return.', expect='The GST summary opens.')
click('tab:Cash ratio', 'Open the Cash ratio tab.', 'The cash ratio compares cash takings with the total and flags an unusual share.', expect='The cash ratio opens.')
click('tab:Exports', 'Open the Exports tab.', 'The Tally export writes the vouchers and the masters in the format the accountant\'s Tally software reads; every report can also be downloaded.', expect='The export options open.')
click('tab:Year end', 'Open the Year end tab.', 'Year end closes the financial year and carries the balances forward. The training only explains it; it is never run in a demo.', expect='The year end page opens.')
click('tab:Bank reconciliation', 'Open the Bank reconciliation tab.', 'Each line of the bank statement is matched with a voucher; unmatched lines are investigated.', expect='The bank reconciliation opens.')
step('Click More sections. Nine more tabs open: Clearing, Day book, Chart of accounts, Parties, Opening balances, Exceptions, Reconciliation, Mapping and Tally export.', 'The rarely used pages are tucked away so that the daily tabs stay short.', target='btn:Clearing', auto=['click:btn:More sections'], action='click', expect='The nine more sections are listed.')
click('tab:Clearing', 'Open the Clearing tab.', 'Clearing accounts hold money in transit, such as card and UPI settlements, until the bank credits them.', expect='The clearing accounts open.')
step('Open the Day book tab.', 'The day book lists every voucher of a day in the order of posting, like the old cash book of the accountant.', expect='The day book opens.', target='tab:Day book', auto=['click:btn:More sections', 'click:tab:Day book'], action='click')
step('Open the Chart of accounts tab.', 'The chart lists every ledger on the 28 groups of Tally; the Owner adds ledgers here.', expect='The chart of accounts opens.', target='tab:Chart of accounts', auto=['click:btn:More sections', 'click:tab:Chart of accounts'], action='click')
step('Open the Parties tab.', 'Companies, vendors and staff have their own sub-ledgers; Shree Agro Industries owes Rs 4,725 for the stay of Vikram Jadhav.', expect='The parties are listed.', target='tab:Parties', auto=['click:btn:More sections', 'click:tab:Parties'], action='click')
step('Open the Opening balances tab.', 'The opening balances at the start of the year are entered by hand once and then locked.', expect='The opening balances open.', target='tab:Opening balances', auto=['click:btn:More sections', 'click:tab:Opening balances'], action='click')
step('Open the Tally export tab.', 'The file contains the masters and the vouchers in the format Tally reads, so the accountant never types them again.', expect='The Tally export page opens.', target='tab:Tally export', auto=['click:btn:More sections', 'click:tab:Tally export'], action='click')
read('The Lock period button at the top is for the Owner: it locks a month after the GST return, so no entry can be added to that month. The training does not lock a month.', 'A locked month protects the figures that were filed.', target='btn:Lock period', expect='The Lock period button.')
